const j = $json || {};
const msg = j.message || j.channel_post || j.edited_message || {};
const chat = msg.chat || {};
const chatId = (chat.id !== undefined && chat.id !== null) ? String(chat.id) : '';

let kind = 'unsupported';
let fileKind = '';
let fileId = '';
let textBody = '';
let url = '';
let mode = 'csv';

function detectMode(s){ s = String(s || '').toLowerCase(); if (/\/csreview\b/.test(s)) return 'csreview'; if (/\/review\b/.test(s)) return 'review'; if (/\/csv\b/.test(s)) return 'csv'; return 'csv'; }

function kindFromMeta(mime, name){
  mime = String(mime || '').toLowerCase();
  name = String(name || '').toLowerCase();
  if (mime.includes('pdf') || name.endsWith('.pdf')) return 'pdf';
  if (mime.includes('csv') || name.endsWith('.csv')) return 'csv';
  if (mime.includes('spreadsheet') || mime.includes('excel') || mime.includes('ms-excel') || name.endsWith('.xlsx') || name.endsWith('.xls')) return 'xlsx';
  if (mime.startsWith('text/') || name.endsWith('.txt')) return 'other';
  return 'other';
}

if (msg.document) {
  const d = msg.document || {};
  fileId = d.file_id || '';
  fileKind = kindFromMeta(d.mime_type, d.file_name);
  mode = detectMode(msg.caption);
  kind = 'document';
} else if (typeof msg.text === 'string' && msg.text.trim().length) {
  textBody = msg.text.trim();
  if (/^\/(start|help)\b/i.test(textBody)) {
    return { json: { chatId, kind: 'start', fileKind, fileId, textBody, url } };
  }
  mode = detectMode(textBody);
  const m = textBody.match(/https?:\/\/[^\s]+/i);
  if (m) {
    url = m[0];
    const schemeMatch = url.match(/^([a-z][a-z0-9+.-]*):/i);
    const scheme = (schemeMatch ? schemeMatch[1] : '').toLowerCase();
    const isHttp = scheme === 'http' || scheme === 'https';
    const authMatch = url.match(/^[a-z][a-z0-9+.-]*:\/\/([^\/?#]*)/i);
    let host = authMatch ? authMatch[1] : '';
    host = host.split('@').pop().replace(/:\d+$/, '').replace(/^\[|\]$/g, '').toLowerCase();
    const isPrivate = !host
      || host === 'localhost' || host.endsWith('.localhost') || host === '0.0.0.0'
      || /^127\./.test(host) || /^10\./.test(host) || /^192\.168\./.test(host)
      || /^169\.254\./.test(host) || /^172\.(1[6-9]|2[0-9]|3[0-1])\./.test(host)
      || host === '::1' || host === 'metadata.google.internal'
      || host.endsWith('.internal') || host.endsWith('.local');
    kind = (!isHttp || isPrivate) ? 'blocked' : 'link';
  } else {
    kind = 'text';
  }
} else if (msg.photo || msg.voice || msg.audio || msg.video || msg.sticker || msg.animation) {
  kind = 'unsupported';
}

return { json: { chatId, kind, fileKind, fileId, textBody, mode, url } };

const MAX = 30000;
let full = String($json.text || "");
const total = full.length;
let rawText = full;
let truncated = false;
if (total > MAX) { rawText = full.slice(0, MAX); truncated = true; }
const used = rawText.length;
const coveragePct = total > 0 ? Math.round((used / total) * 100) : 100;
return { json: { rawText, _charsTotal: total, _charsUsed: used, _truncated: truncated, _coveragePct: coveragePct } };

const items = $input.all();
let rows = [];
for (const it of items) {
  const out = it.json.output ?? it.json;
  if (Array.isArray(out)) rows = rows.concat(out);
  else if (out && Array.isArray(out.rows)) rows = rows.concat(out.rows);
  else if (out && typeof out === "object") rows.push(out);
}
rows = rows.filter((r) => r && typeof r === "object" && !Array.isArray(r) && !("__empty" in r));
if (rows.length === 0) { return [{ json: { __empty: true } }]; }
const seen = new Set(); const columns = [];
for (const r of rows) { for (const k of Object.keys(r)) { if (!seen.has(k)) { seen.add(k); columns.push(k); } } }
const normalized = rows.map((r) => {
  const clean = {};
  for (const col of columns) {
    let v = r[col];
    if (v === undefined || v === "" || v === "N/A" || v === "null") v = null;
    if (typeof v === "object" && v !== null) v = JSON.stringify(v);
    clean[col] = v;
  }
  return clean;
});
return normalized.map((json) => ({ json }));

let cov = null, trunc = false;
for (const n of ["Normalize (Link)", "Normalize (PDF)", "Normalize (Text File)"]) {
  try { const j = $(n).first().json; if (j && j._coveragePct !== undefined) { cov = j._coveragePct; trunc = !!j._truncated; break; } } catch (e) {}
}
let caption = "CuraBot: seu CSV limpo está pronto.";
if (trunc && cov !== null) { caption += "\n\n⚠️ Transparência: processei apenas " + cov + "% do conteúdo (arquivo/página muito grande, cortado em 30.000 caracteres para caber no limite de tokens)."; }
return [{ json: { _caption: caption }, binary: $input.first().binary }];

const rows = $input.all().map((i) => i.json);
const preview = JSON.stringify(rows).slice(0, 12000);
return [{ json: { reviewInput: "Dataset with " + rows.length + " records. Data (JSON):\n" + preview } }];

const rows = $input.all().map((i) => i.json);
const seen = {};
const columns = [];
for (const r of rows) { for (const k of Object.keys(r || {})) { if (!seen[k]) { seen[k] = true; columns.push(k); } } }
return [{ json: { columnsText: columns.join(", "), rowCount: rows.length, columns, rowsJson: rows } }];

const src = $("Collect Rows").first().json;
const rows = Array.isArray(src.rowsJson) ? src.rowsJson : [];
const inFirst = $input.first() && $input.first().json ? $input.first().json : {};
const aiOut = inFirst.output !== undefined ? inFirst.output : inFirst;
const mappings = (aiOut && Array.isArray(aiOut.mappings)) ? aiOut.mappings : [];
const map = {};
for (const m of mappings) { if (m && m.source) map[String(m.source)] = m; }
function snake(k){ return String(k || "").trim().toLowerCase().replace(/[^a-z0-9]+/g, "_").replace(/^_+|_+$/g, "") || "column"; }
function detectMult(s){ s = String(s).toLowerCase(); if (/(milh|\bmi\b|\bmm\b)/.test(s)) return 1000000; if (/\bmil\b/.test(s) || /[0-9]\s*k\b/.test(s)) return 1000; return 1; }
function toNumber(v, integer){
  if (v === null || v === undefined || v === "") return null;
  let s = String(v).trim().toLowerCase();
  const mult = detectMult(s);
  s = s.split(/\s*(?:-|–|—|to|a|ate|até)\s*/)[0];
  s = s.replace(/[^0-9.,-]/g, "");
  if (s === "" || s === "-") return null;
  const lastComma = s.lastIndexOf(","); const lastDot = s.lastIndexOf(".");
  if (lastComma > -1 && lastDot > -1) { if (lastComma > lastDot) { s = s.replace(/\./g, "").replace(/,/g, "."); } else { s = s.replace(/,/g, ""); } }
  else if (lastComma > -1) { const after = s.length - lastComma - 1; if (after === 3) s = s.replace(/,/g, ""); else s = s.replace(/,/g, "."); }
  else { const dots = (s.match(/\./g) || []).length; if (dots > 1) { s = s.replace(/\./g, ""); } else if (dots === 1) { const afterDot = s.length - s.lastIndexOf(".") - 1; if (afterDot === 3) s = s.replace(/\./g, ""); } }
  let n = parseFloat(s); if (isNaN(n)) return null; n = n * mult; return integer ? Math.round(n) : n;
}
function currencyCode(v){ const s = String(v); if (/r\$|brl|reais/i.test(s)) return "BRL"; if (/us\$|usd|\$/i.test(s)) return "USD"; if (/eur|€/i.test(s)) return "EUR"; if (/gbp|£/i.test(s)) return "GBP"; return null; }
function toISODate(v){
  if (v === null || v === undefined || v === "") return null;
  const s = String(v).trim();
  let m = s.match(/^(\d{4})-(\d{2})-(\d{2})/); if (m) return m[1] + "-" + m[2] + "-" + m[3];
  m = s.match(/^(\d{1,2})[\/.-](\d{1,2})[\/.-](\d{2,4})$/);
  if (m) { let d = ("0" + m[1]).slice(-2); let mo = ("0" + m[2]).slice(-2); let y = m[3]; if (y.length === 2) y = "20" + y; return y + "-" + mo + "-" + d; }
  const t = Date.parse(s); if (!isNaN(t)) return new Date(t).toISOString().slice(0, 10); return s;
}
function looksDate(v){ const s = String(v); return /^\d{4}-\d{2}-\d{2}/.test(s) || /^\d{1,2}[\/.-]\d{1,2}[\/.-]\d{2,4}$/.test(s); }
function looksNumeric(v){ const s = String(v).replace(/\s/g, ""); if (!/[0-9]/.test(s)) return false; return s.replace(/[0-9.,%+\-–—kmil$r€£]/gi, "").length === 0; }
const out = rows.map((r) => {
  const clean = {};
  for (const key of Object.keys(r || {})) {
    const val = r[key]; const m = map[key] || {};
    const target = m.target ? snake(m.target) : snake(key);
    let type = m.type || "auto";
    if (type === "auto") { if (looksDate(val)) type = "date"; else if (looksNumeric(val)) type = "number"; else type = "string"; }
    if (type === "currency") { clean[target] = toNumber(val, false); clean[target + "_currency"] = currencyCode(val); }
    else if (type === "integer") { clean[target] = toNumber(val, true); }
    else if (type === "number") { clean[target] = toNumber(val, false); }
    else if (type === "date") { clean[target] = toISODate(val); }
    else { clean[target] = (val === "" || val === null || val === undefined) ? null : String(val).trim(); }
  }
  return clean;
});
if (out.length === 0) return [{ json: { __empty: true } }];
return out.map((json) => ({ json }));

const MAX = 30000;
let full = String($json.text || "");
const total = full.length;
let rawText = full;
let truncated = false;
if (total > MAX) { rawText = full.slice(0, MAX); truncated = true; }
const used = rawText.length;
const coveragePct = total > 0 ? Math.round((used / total) * 100) : 100;
return { json: { rawText, _charsTotal: total, _charsUsed: used, _truncated: truncated, _coveragePct: coveragePct } };

let html = String($json.data || "");
html = html.replace(/<script[\s\S]*?<\/script>/gi, " ").replace(/<style[\s\S]*?<\/style>/gi, " ").replace(/<[^>]+>/g, " ");
html = html.replace(/&nbsp;/g, " ").replace(/&amp;/g, "&").replace(/&lt;/g, "<").replace(/&gt;/g, ">").replace(/&quot;/g, '"').replace(/\s+/g, " ").trim();
const MAX = 30000;
const total = html.length;
let rawText = html;
let truncated = false;
if (total > MAX) { rawText = html.slice(0, MAX); truncated = true; }
const used = rawText.length;
const coveragePct = total > 0 ? Math.round((used / total) * 100) : 100;
return { json: { rawText, _charsTotal: total, _charsUsed: used, _truncated: truncated, _coveragePct: coveragePct } };
